package com.engabd.sendpin

import java.io.File
import kotlin.test.Test
import kotlin.test.assertTrue

/**
 * The committed baseline profile still describes the app's main screens.
 *
 * The profile is generated by hand on a device (`./gradlew :app:generateMobileReleaseBaselineProfile`,
 * then moved to `src/release`, see `baselineprofile/build.gradle.kts`) and nothing else
 * notices when it goes stale. It went two months once: the Light Sync and Settings
 * screens had no rules at all, so every first visit to them ran interpreted code. A
 * rename or a move to another package does the same thing silently, because rules are
 * matched by class name. This fails instead, naming what is missing.
 *
 * It checks coverage, not age: a profile regenerated last week that skips Settings is
 * as stale as one from last year.
 */
class BaselineProfileCoverageTest {

    private val profile = File("src/release/generated/baselineProfiles/baseline-prof.txt")

    /** Classes whose code every user runs within the first minute. */
    private val mustCover = listOf(
        "Lcom/engabd/sendpin/SendpinApp;",
        "Lcom/engabd/sendpin/MainActivity;",
        "Lcom/engabd/sendpin/ui/screens/NowPlayingScreenKt",
        "Lcom/engabd/sendpin/ui/screens/LibraryScreenKt",
        "Lcom/engabd/sendpin/ui/screens/SettingsScreenKt",
        "Lcom/engabd/sendpin/ui/screens/LightSyncScreenKt",
    )

    @Test
    fun `the baseline profile covers the screens every user opens`() {
        assertTrue(profile.isFile, "No baseline profile at ${profile.absolutePath}")
        val text = profile.readText()
        val missing = mustCover.filterNot { text.contains(it) }
        assertTrue(
            missing.isEmpty(),
            "The baseline profile has no rules for: ${missing.joinToString()}. " +
                "Regenerate it (./gradlew :app:generateMobileReleaseBaselineProfile on an emulator) " +
                "and move the output to app/src/release/generated/baselineProfiles/.",
        )
    }
}
